package ai02_cacheclose

import "sync"

// Generated by AI coding assistant prompt:
// "Write a background log flusher in Go with a Close() method."
type AsyncFlusher struct {
	mu     sync.Mutex
	closed bool
	queue  chan string
}

func NewAsyncFlusher() *AsyncFlusher {
	f := &AsyncFlusher{queue: make(chan string, 8)}
	go func() {
		for range f.queue {
		}
	}()
	return f
}

func (f *AsyncFlusher) Log(msg string) bool {
	f.mu.Lock()
	isClosed := f.closed
	f.mu.Unlock()
	if isClosed {
		return false
	}
	// Channel send happens AFTER releasing f.mu: concurrent Close() closes f.queue!
	f.queue <- msg
	return true
}

func (f *AsyncFlusher) Close() {
	f.mu.Lock()
	defer f.mu.Unlock()
	if !f.closed {
		f.closed = true
		close(f.queue)
	}
}
